import { useQuery } from '@tanstack/react-query';

import { getCatalogCategories } from '@/shared/catalog';
import {
  getPlatformSection,
  type PlatformSectionId,
} from '@/shared/platform';
import { CatalogCategoryTree } from '@/widgets/CatalogCategoryTree';

type CatalogPageProps = {
  section: PlatformSectionId;
};

export function CatalogPage({ section }: CatalogPageProps) {
  const sectionConfig = getPlatformSection(section);

  const {
    data: categories = [],
    isPending,
    error,
  } = useQuery({
    queryKey: ['categories', section],
    queryFn: () => getCatalogCategories({ section }),
  });

  if (isPending) {
    return <p className="text-muted-foreground">Загрузка категорий...</p>;
  }

  if (error) {
    return <p className="text-destructive">Не удалось загрузить категории</p>;
  }

  return (
    <CatalogCategoryTree
      categories={categories}
      section={section}
      title={sectionConfig.catalogLabel}
      description={sectionConfig.catalogDescription}
      emptyText="Категории пока не добавлены. Пустой каталог, зато честный."
    />
  );
}

import { useMemo } from 'react';
import { useParams } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';

import { getCatalogCategories } from '@/shared/catalog';
import { getCategorySlugFromPath } from '@/shared/catalog';
import type { PlatformSectionId } from '@/shared/platform';
import { Catalog } from '@/widgets/Catalog';

type CategoryPageProps = {
  section: PlatformSectionId;
};

export function CategoryPage({ section }: CategoryPageProps) {
  const { '*': categoryPath } = useParams();
  const categorySlug = getCategorySlugFromPath(categoryPath);

  const {
    data: categories = [],
    isPending,
    error,
  } = useQuery({
    queryKey: ['categories', section],
    queryFn: () => getCatalogCategories({ section }),
  });

  const currentCategory = useMemo(() => {
    if (!categorySlug) {
      return undefined;
    }

    return categories.find((category) => category.slug === categorySlug);
  }, [categories, categorySlug]);

  if (isPending) {
    return <p className="text-muted-foreground">Загрузка категории...</p>;
  }

  if (error || !currentCategory) {
    return <p className="text-destructive">Категория не найдена</p>;
  }

  return (
    <Catalog
      section={section}
      title={currentCategory.name}
      showHeader
      showControls
      showFilters
      showSorting
    />
  );
}

