      .setTitle('DNA API')
      .setDescription('DNA marketplace API')
      .setVersion('1.0')
      .addBearerAuth()
      .build(),
  );
  SwaggerModule.setup('api/docs', app, openApiDocument);
  app.enableCors({
    origin: webAppUrl,
  });

  await app.listen(configService.getOrThrow<number>('PORT'), '0.0.0.0');
}

